import { IngestPipeline } from "@514labs/moose-lib";

// User Activity Events Data Model
export interface UserActivity {
  eventId: string;
  eventTs: Date;
  userId: string;
  action: string;
  durationMs: number; // Will default null values to 0 in transformation
}

// Ingest Pipeline with optimized ordering for query patterns:
// 1. Activity counts per user over date range (userId, eventTs)
// 2. Total duration per action type (action)
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["userId", "action", "eventTs"]
  },
  stream: true,
  ingestApi: true,
});

