const fs = require('fs');
const path = require('path');

// Read and parse the CSV file
function loadSampleData() {
  const csvPath = '/data/samples/user_activity_sample.csv';
  const csvContent = fs.readFileSync(csvPath, 'utf-8');
  const lines = csvContent.trim().split('\n');
  const headers = lines[0].split(',');

  const events = [];

  // Process each data row (skip header)
  for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(',');
    if (values.length >= 5) {
      const event = {
        eventId: values[0].trim(),
        eventTs: values[1].trim(),
        userId: values[2].trim(),
        action: values[3].trim(),
        durationMs: parseFloat(values[4].trim()) || 0  // Default null/empty to 0
      };
      events.push(event);
    }
  }

  return events;
}

// Post data to Moose ingest API
async function postEvents(events) {
  const INGEST_URL = 'http://localhost:4000/ingest/UserActivity';

  for (const event of events) {
    try {
      const response = await fetch(INGEST_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(event)
      });

      if (response.ok) {
        console.log(`✓ Ingested event: ${event.eventId}`);
      } else {
        console.error(`✗ Failed to ingest ${event.eventId}: ${response.status}`);
        const errorText = await response.text();
        console.error(`Error: ${errorText}`);
      }
    } catch (error) {
      console.error(`✗ Error posting event ${event.eventId}:`, error.message);
    }
  }
}

// Main execution
async function main() {
  console.log('Loading sample user activity data...');

  try {
    const events = loadSampleData();
    console.log(`Loaded ${events.length} events from CSV`);

    console.log('Ingesting events into Moose...');
    await postEvents(events);

    console.log('Data loading complete!');
  } catch (error) {
    console.error('Error loading data:', error.message);
    process.exit(1);
  }
}

main();

